    "SVTCA[x] PUSHW -1 0 SFVFS PUSHB 0 SZPS PUSHB 0 PUSHW 100 SCFS PUSHB 0 SRP0 PUSHW 2000 SCVTCI "
    "PUSHB 1 8 MIRP[00100] FLIPOFF PUSHB 2 8 MIRP[00100] PUSHB 68 SCVTCI PUSHB 3 8 MIRP[00100] "
