# ==============================================================================================
# The 0.8.1 verification round: rows the reviewers probed FreeType with. Each keeps the probe's
# intent; each carries a check that the wrong reading would have answered differently.
# ==============================================================================================

# --- the projection fast path: a component EXACTLY 0x4000 selects Project_x / Project_y ---------
# Compute_Funcs (ref2143/ttinterp.c:2281-2293) keys the projection on projVector.x == 0x4000 (then
# .y == 0x4000) and Project_x/Project_y answer the one component alone, whatever the other holds;
# the same two tests pick the dual projection from dualVector. Normalize does hand back such
# vectors: SPVFS 236 1 is (0x4000, 69), and the outline's own 2-0 edge at 40 ppem and 12-1 edge at
# 16 ppem land there through SPVTL. Every measurement below would differ by round(dy * 69 / 16384)
# under the general dot product.
_OPS5_X = ("PUSHB 0 SRP0 PUSHB 5 PUSHW 400 MSIRP[0] PUSHB 4 MDAP[1] PUSHB 0 SRP0 PUSHB 6 MDRP[00100] "
           "PUSHB 7 8 MIRP[00000] PUSHB 11 10 MIAP[1]")
_OPS5_Y = ("PUSHB 0 SRP0 PUSHB 4 PUSHW 400 MSIRP[0] PUSHB 5 MDAP[1] PUSHB 0 SRP0 PUSHB 6 MDRP[00100] "
           "PUSHB 7 8 MIRP[00000] PUSHB 11 10 MIAP[1]")
program(
    "pv_xfast_ops", 48,
    "SPVFS 236 1 makes PV = DV = (0x4000, 69): MSIRP 5, MDAP[1] 4, MDRP[00100] 6, MIRP[00000] 7 and MIAP[1] 11 all measure dx ALONE (Project_x); the general dot product lands each 1-5 units off at 48 ppem",
    "SVTCA[x] PUSHW 236 1 SPVFS " + _OPS5_X,
    check="pv_ops",
)
program(
    "pv_yfast_ops", 48,
    "SPVFS 1 236 makes PV = DV = (69, 0x4000): the same five instructions along y measure dy alone (Project_y)",
    "SVTCA[y] PUSHW 1 236 SPVFS " + _OPS5_Y,
    check="pv_ops",
)
program(
    "pv_xfast_spvtl", 40,
    "SPVTL[0] 2 0 at 40 ppem: the edge (765, 2) normalises to (0x4000, 42), the way a real font reaches Project_x; the same five instructions along x",
    "PUSHB 2 0 SPVTL[0] SFVTCA[x] " + _OPS5_X,
    check="pv_ops",
)
program(
    "pv_yfast_spvtl", 16,
    "SPVTL[0] 12 1 at 16 ppem: the edge (-1, 295) normalises to (-55, 0x4000), Project_y; the same five instructions along y",
    "PUSHB 12 1 SPVTL[0] SFVTCA[y] " + _OPS5_Y,
    check="pv_ops",
)
program(
    "pv_xfast_mdap", 12,
    "MDAP[1] on 4 under PV (0x4000, 69) rounds its plain x (Project_x); the general product would read 4's x plus 1",
    "SVTCA[x] PUSHW 236 1 SPVFS PUSHB 4 MDAP[1]",
    check="pv_mdap",
)
program(
    "pv_yfast_mdap", 12,
    "MDAP[1] on 4 under PV (69, 0x4000) rounds its plain y (Project_y)",
    "SVTCA[y] PUSHW 1 236 SPVFS PUSHB 4 MDAP[1]",
    check="pv_mdap",
)
program(
    "pv_xfast_mdap_pair", 12,
    "MDAP[1] on 5 (304, 305) and 4 under PV (0x4000, 69): 5's projection is 304 exactly and lands on 320",
    "SVTCA[x] PUSHW 236 1 SPVFS PUSHB 5 MDAP[1] PUSHB 4 MDAP[1]",
    check="pv_mdap",
)
program(
    "pv_xfast_gc0", 12,
    "GC[0] of 4 under PV (0x4000, 69) is cur.x alone; SCFS puts it on point 1 under the same projection",
    "SVTCA[x] PUSHW 236 1 SPVFS PUSHB 4 GC[0] PUSHB 1 SWAP SCFS",
    check="pv_readout",
)
program(
    "dv_xfast_gc1", 12,
    "SPVFS copies the vector onto the DUAL: GC[1] of 4 is org.x alone (the dual's Project_x); SCFS onto 1",
    "SVTCA[x] PUSHW 236 1 SPVFS PUSHB 4 GC[1] PUSHB 1 SWAP SCFS",
    check="pv_readout",
)
program(
    "pv_xfast_md0", 12,
    "MD[0] between 4 and 0 under PV (0x4000, 69) is the plain x difference of cur; SCFS onto 1",
    "SVTCA[x] PUSHW 236 1 SPVFS PUSHB 4 0 MD[0] PUSHB 1 SWAP SCFS",
    check="pv_readout",
)
program(
    "pv_xfast_gc0_twilight", 12,
    "GC[0] of twilight 0 at (100, 3000) under PV (0x4000, 69) is 100, read into 13; the general product would read 113",
    place(0, 100, 3000) + " PUSHW 236 1 SPVFS PUSHB 0 SZP2 PUSHB 0 GC[0] PUSHB 1 SZP2 SVTCA[x] PUSHB 13 SWAP SCFS",
    check="pv_twilight_readout",
)
program(
    "dv_xfast_gc1_twilight", 12,
    "GC[1] (org, the dual) of twilight 0 at (100, 3000) under DV (0x4000, 69) is 100 too, read into 12",
    place(0, 100, 3000) + " PUSHW 236 1 SPVFS PUSHB 0 SZP2 PUSHB 0 GC[1] PUSHB 1 SZP2 SVTCA[x] PUSHB 12 SWAP SCFS",
    check="pv_twilight_readout",
)
program(
    "pv_yfast_gc0_twilight", 12,
    "GC[0] of twilight 2 at (3000, 100) under PV (69, 0x4000) is 100 (Project_y), read into 10",
    place(2, 3000, 100) + " PUSHW 1 236 SPVFS PUSHB 0 SZP2 PUSHB 2 GC[0] PUSHB 1 SZP2 SVTCA[y] PUSHB 10 SWAP SCFS",
    check="pv_twilight_readout",
)
program(
    "pv_xfast_round_flip", 12,
    "twilight 1 at (31, 3000) under PV (0x4000, 69), FV x: MDAP[1] projects 31 and rounds it to 0; the general 44 would round UP to 64, a different pixel; read back into 11",
    place(1, 31, 3000) + " PUSHW 236 1 SPVFS SFVTCA[x] PUSHB 0 SZP0 PUSHB 1 MDAP[1] PUSHB 1 SZP0 " + read_twilight(1, 11),
    check="pv_round_flip",
)
program(
    "pv_xfast_spvtl_18", 18,
    "SPVTL[0] 2 0 at 18 ppem normalises to (0x4000, 47): MDAP[1] on 5 and 4 round their plain x",
    "PUSHB 2 0 SPVTL[0] SFVTCA[x] PUSHB 5 MDAP[1] PUSHB 4 MDAP[1]",
    check="pv_mdap",
)
program(
    "dv_xfast_sdpvtl", 12,
    "SDPVTL[0] 4 3 on twilight org (236, 1) makes the DUAL (0x4000, 69): MD[1] (original) from 5 at (100, 3000) to 3 and GC[1] of 5 are both 100 under the dual's Project_x; into 9 and 8",
    place(4, 236, 1) + " " + place(5, 100, 3000) + " PUSHB 0 SZPS PUSHB 4 3 SDPVTL[0] PUSHB 5 3 MD[1] PUSHB 5 GC[1] "
    "PUSHB 1 SZP2 SVTCA[x] PUSHB 8 SWAP SCFS PUSHB 9 SWAP SCFS",
    check="dv_sdpvtl",
)
program(
    "fv_xfast_sfvtl", 18,
    "SFVTL[0] 2 0 at 18 ppem gives FV (0x4000, 47) with PV x: the X-only MOVE path, MSIRP 9 by 800 moves x alone where the general move vector would shift y by 2",
    "SVTCA[x] PUSHB 2 0 SFVTL[0] PUSHB 0 SRP0 PUSHB 9 PUSHW 800 MSIRP[0]",
    check="fv_sfvtl",
)

# --- the single-width sign restore, and the strict window ---------------------------------------
program(
    "mdrp_swidth_negative", 12,
    "SSW -200 (-150 at 12 ppem) with SSWCI 250: MDRP from 0 to 8 (org_dist 75, inside the window) takes -150 — the sign is read from the ORIGINAL distance once, not from the value just stored; 9 (151) is outside the window and stays",
    "SVTCA[x] PUSHW -200 SSW PUSHB 250 SSWCI PUSHB 0 SRP0 PUSHB 8 MDRP[00000] PUSHB 9 MDRP[00000]",
    check="swidth_negative",
)
program(
    "mirp_swidth_negative", 12,
    "the same on MIRP with FLIPOFF (auto-flip would mask it) and cvt 5 = 0, inside the window for both: cvt_dist becomes -150 for 8 and 9, not +150",
    "SVTCA[x] FLIPOFF PUSHW 2000 SCVTCI PUSHW -200 SSW PUSHB 250 SSWCI PUSHB 0 SRP0 PUSHB 8 5 MIRP[00000] "
    "PUSHB 9 5 MIRP[00000]",
    check="swidth_negative",
)
program(
    "mdrp_swidth_below", 12,
    "SSW 4 (3) with SSWCI 10: MDRP from 3 to 4 has org_dist -4, inside the window, and takes -3: the negative branch of the restore",
    "SVTCA[x] PUSHB 4 SSW PUSHB 10 SSWCI PUSHB 3 SRP0 PUSHB 4 MDRP[00000]",
    check="mdrp_swidth_below",
)
program(
    "mirp_swidth_below", 12,
    "SSW 100 (75) with SSWCI 200 and cvt 4 (-76): MIRP's cvt_dist is inside the window and negative, so it becomes -75",
    "SVTCA[x] PUSHW 2000 SCVTCI PUSHB 100 SSW PUSHB 200 SSWCI PUSHB 4 SRP0 PUSHB 9 4 MIRP[00000]",
    check="mirp_swidth_below",
)
