# ----------------------------------------------------------------------------------------------
# Running a program through FreeType
# ----------------------------------------------------------------------------------------------
def hint_once(code, ppem, font):
    """FreeType's answer for `code` in glyph 1 of font variant `font` at `ppem`: the unhinted
    outline, then the hinted points/tags/advance from a fresh face, then the same load under
    FT_LOAD_PEDANTIC on ANOTHER fresh face (the flag is sticky per size), which must succeed."""
    data = build_font(code, max_program_len(), font)
    face = ftshim.load_face(data)
    raw = ftshim.hinted(face, ppem, 1, hint=False)
    points, tags, advance = ftshim.hinted(face, ppem, 1)
    ftshim.done(face)
    strict = ftshim.load_face(data)
    try:
        p2, t2, a2 = ftshim.hinted(strict, ppem, 1, pedantic=True)
    finally:
        ftshim.done(strict)
    assert (p2, t2, a2) == (points, tags, advance), "pedantic and default loads disagree"
    assert len(points) == NPTS, len(points)
    return {"code": code, "raw": raw, "points": points, "tags": tags, "advance": advance}


def run_program(prog):
    """Hint `prog` on its font variant at its ppem, pedantic-clean or the script stops."""
    try:
        r = hint_once(asm(prog["text"]), prog["ppem"], prog["font"])
    except ftshim.FTError as e:
        sys.exit("program %s: FreeType refused it under FT_LOAD_PEDANTIC (%s) - fix the program" % (prog["name"], e))
    r["font"] = prog["font"]
    return r


def max_program_len():
    lens = [len(asm(p["text"])) for p in PROGRAMS]
    lens += [len(prep_bytes(f)) for f in range(len(FONTS))] + [len(fpgm_bytes(f)) for f in range(len(FONTS))]
    return max(lens + [16])


def base_font(f):
    """Font variant `f` as the module embeds it: the glyph with NO program, so a consumer sees
    the outline, the tables and the limits exactly as every program's font had them."""
    return build_font(b"", max_program_len(), f)


def scaled_outline(ppem):
    s = scale_for(ppem)
    return [(mulfix(x, s), mulfix(y, s)) for x, y, _ in OUTLINE]


# ----------------------------------------------------------------------------------------------
# Non-degeneracy checks: what the WRONG reading of a row would give, asserted != FreeType's.
# ----------------------------------------------------------------------------------------------
def _org():
    return scaled_outline(12)


def _orus():
    return [(x, y) for x, y, _ in OUTLINE]


def check_mdrp_orus(r):
    org = _org()
    wrong = org[0][0] + (org[3][0] - org[0][0])  # org - org: the point would not move at all
    assert r["points"][3][0] != wrong, "mdrp_orus: org and orus readings coincide, pick other points"


def check_md_orus(r):
    org = _org()
    wrong = org[3][0] - org[0][0]
    assert r["points"][13][0] != wrong, "md_orus: org and orus readings coincide"


def check_ip_orus(r):
    org = _org()
    cur_range = r["points"][1][0] - org[0][0]
    for p in (2, 9):
        wrong = org[0][0] + muldiv(org[p][0] - org[0][0], cur_range, org[1][0] - org[0][0])
        assert r["points"][p][0] != wrong, "ip_orus: point %d agrees with the org reading" % p


def check_isect(r):
    """Both ISECT branches are taken: the first crossing is far from grazing, the second is."""
    org = _org()
    pp = [(mulfix(x, scale_for(12)), mulfix(y, scale_for(12))) for x, y in phantoms()]
    pp[0] = (pix_round(pp[0][0]), 0)
    pp[1] = (pix_round(pp[1][0]), 0)
    pts = org + pp

    def grazing(a0, a1, b0, b1):
        dbx, dby = pts[b1][0] - pts[b0][0], pts[b1][1] - pts[b0][1]
        dax, day = pts[a1][0] - pts[a0][0], pts[a1][1] - pts[a0][1]
        disc = muldiv(dax, -dby, 0x40) + muldiv(day, dbx, 0x40)
        dot = muldiv(dax, dbx, 0x40) + muldiv(day, dby, 0x40)
        return not (19 * abs(disc) > abs(dot))

    assert not grazing(0, 4, 2, 6), "isect: lines 0-4 and 2-6 count as grazing"
    assert grazing(0, 2, PP1, PP2), "isect: lines 0-2 and pp1-pp2 do not take the /4 fallback"


def check_near_perp(r):
    fx1 = normalize(1, 20)[0]
    fx2 = normalize(1, 12)[0]
    assert -0x400 < fx1 < 0x400, "near_perp: (1, 20) is not in the orthogonal band (%d)" % fx1
    assert fx2 >= 0x400, "near_perp: (1, 12) is in the orthogonal band (%d)" % fx2
    assert r["points"][2] == r["raw"][0][2] and r["tags"][2] == 1, "near_perp: point 2 moved or was touched"
    assert r["points"][4] != r["raw"][0][4] and r["tags"][4] & 0x18 == 0x18, "near_perp: point 4 did not move"


def check_b1(r):
    org = _org()
    pv = normalize(36, 35)[:2]
    fdp = (pv[0] * 0x4000 + 0x2000) >> 14
    move = 175 - dotfix14(org[9][0] - org[0][0], org[9][1] - org[0][1], pv[0], pv[1])
    assert move == 19, "b1: the MSIRP moves by %d, not 19" % move
    wrong = org[9][0] + muldiv(move, 0x4000, fdp)  # 2.13.2's FT_MulDiv(d, fv, F_dot_P)
    assert r["points"][9][0] != wrong, "b1: 2.13.2 and 2.14.3 agree on this move, pick another"


def check_fdotp_edge(r):
    org = _org()
    pv = normalize(64, 1)[:2]
    fdp = (pv[0] * 0x4000 + 0x2000) >> 14
    assert fdp == 0x3FFE, "fdotp_edge: F_dot_P is 0x%X, not 0x3FFE" % fdp
    move = 24576 - dotfix14(org[9][0] - org[0][0], org[9][1] - org[0][1], pv[0], pv[1])
    wrong = org[9][0] + mulfix(move, (0x4000 * 0x10000) // fdp)  # the general regime
    assert r["points"][9][0] != wrong, "fdotp_edge: the fast path and the general path agree here"


def check_normlen(r):
    org = _org()
    dx, dy = org[0][0] - org[3][0], org[0][1] - org[3][1]
    vx, vy, l = normlen(dx, dy)
    assert l > 0x10000, "normlen: the 0-3 line prenormalises to %d, not over 0x10000" % l
    port = (int(vx / 4), int(vy / 4))
    got = (r["points"][13][0], r["points"][12][0])
    assert got == port, "normlen: the FT_Vector_NormLen port answers %s, FreeType %s" % (port, got)


def check_sdpvtl(r):
    org = _org()
    orus = _orus()
    s = scale_for(12)
    cur4 = (org[4][0] + 300, org[4][1])
    proj = normalize(org[0][0] - cur4[0], org[0][1] - cur4[1])[:2]
    fdp = (proj[0] * 0x4000 + 0x2000) >> 14
    mv = int((0x4000 * 0x10000) / fdp)
    org_dist = mulfix(dotfix14(orus[9][0] - orus[0][0], orus[9][1] - orus[0][1], proj[0], proj[1]), s)
    cur_dist = dotfix14(org[9][0] - org[0][0], org[9][1] - org[0][1], proj[0], proj[1])
    wrong = org[9][0] + mulfix(org_dist - cur_dist, mv)  # the projection used as the dual too
    assert r["points"][9][0] != wrong, "sdpvtl: dual and projection readings agree here"


def check_sloop_order(r, prog):
    """The loop instruction took the TOP n values: the first value pushed (the leftover) is the
    one SHPIX moved by exactly 64 along the axis, and none of the loop's points moved by that."""
    toks = prog["text"].split()
    n = int(toks[toks.index("SLOOP") - 1])
    at = toks.index("SLOOP") + 2
    assert toks[at - 1] == "PUSHB", prog["name"]
    pushed = [int(t) for t in toks[at : at + n + 1]]
    leftover, looped = pushed[0], pushed[1:]
    axis = 0 if toks[0] == "SVTCA[x]" else 1
    shift = [0, 0]
    shift[axis] = 64
    d = (r["points"][leftover][0] - r["raw"][0][leftover][0], r["points"][leftover][1] - r["raw"][0][leftover][1])
    assert d == tuple(shift), "%s: the leftover point %d moved by %s, not %s" % (prog["name"], leftover, d, shift)
    for p in looped:
        dp = (r["points"][p][0] - r["raw"][0][p][0], r["points"][p][1] - r["raw"][0][p][1])
        assert dp != tuple(shift), "%s: looped point %d moved by the SHPIX amount; pick another" % (prog["name"], p)
        assert dp != (0, 0) or r["tags"][p] != r["raw"][1][p], "%s: looped point %d unchanged" % (prog["name"], p)


def check_near_vertical(r, prog):
    org = _org()
    pv = normalize(org[4][0] - org[3][0], org[4][1] - org[3][1])
    assert -0x400 < pv[0] < 0x400, "near_vertical: pvx %d is outside the orthogonal band" % pv[0]
    assert r["points"][9] == r["raw"][0][9], "near_vertical: point 9 moved"
    assert r["tags"][9] == r["raw"][1][9] | 0x08, "near_vertical: point 9 tag %d" % r["tags"][9]
    assert r["points"][11] == r["raw"][0][11] and r["tags"][11] == r["raw"][1][11], "near_vertical: 11 moved or touched"
    assert r["points"][2] != r["raw"][0][2], "near_vertical: rp1 (point 2) was not displaced"


def check_xonly_fast(r, prog):
    fv = normalize(236, 1)[:2]
    assert fv == (0x4000, 69), "xonly_fast: SFVFS 236 1 normalises to %s" % (fv,)
    dx9 = r["points"][9][0] - r["raw"][0][9][0]
    assert mulfix(dx9, fv[1] * 4) != 0, "xonly_fast: the general path would not have moved y either"
    assert r["points"][9][1] == r["raw"][0][9][1] and r["tags"][9] == r["raw"][1][9] | 0x08, "xonly_fast: 9"
    assert r["points"][11][1] == r["raw"][0][11][1] and r["tags"][11] == r["raw"][1][11] | 0x18, "xonly_fast: 11"
    dy13 = r["points"][13][1] - r["raw"][0][13][1]
    assert mulfix(dy13, fv[1] * 4) != 0, "xonly_fast: the general path would not have moved x either"
    assert r["points"][13][0] == r["raw"][0][13][0] and r["tags"][13] == r["raw"][1][13] | 0x10, "xonly_fast: 13"


def check_rthg_sround(r, prog):
    """Every rounded distance here differs from what RTG would have given."""
    orus = _orus()
    s = scale_for(12)
    org = _org()

    def rtg(d):
        return pix_round(d) if d >= 0 else -pix_round(-d)

    for ref, p in ((0, 9), (2, 6), (0, 13), (0, 4)):
        d = mulfix(orus[p][0] - orus[ref][0], s)
        wrong = org[ref][0] + rtg(d)
        assert r["points"][p][0] != wrong, "rthg_sround: point %d agrees with RTG (%d)" % (p, wrong)


def check_alignpts_small(r, prog):
    raw = r["raw"][0]
    assert raw[4][0] - raw[3][0] == -3 and raw[4][1] - raw[12][1] == 3, "alignpts_small: the pairs are not 3/64 apart"
    assert r["points"][3][0] == raw[3][0] - 1 and r["points"][4][0] == raw[4][0] + 1, "alignpts_small: x"
    assert r["points"][12][1] == raw[12][1] + 1 and r["points"][4][1] == raw[4][1] - 1, "alignpts_small: y"


def check_isect_parallel(r, prog):
    assert r["points"][13] == (200, 150) and r["points"][12] == (150, 150), "isect_parallel: not the /4 average"
    assert r["tags"][13] & 0x18 == 0x18 and r["tags"][12] & 0x18 == 0x18, "isect_parallel: touch bits"


def _check_sdpvtl_after_mdap(r, rotate):
    """Point 11 was moved by MDAP[1] along x; the 0-11 line then gives the dual from org and the
    projection from cur (rotated a quarter turn when `rotate`); the MDRP to 8 from rp0 = 0 must
    differ from a reading that uses the projection as the dual too."""
    org, orus, s = _org(), _orus(), scale_for(12)
    cur11 = (pix_round(org[11][0]), org[11][1])
    assert r["points"][11][0] == cur11[0], "sdpvtl_mdap: point 11 is at %d, not %d" % (r["points"][11][0], cur11[0])
    dual = normalize(org[0][0] - org[11][0], org[0][1] - org[11][1])[:2]
    proj = normalize(org[0][0] - cur11[0], org[0][1] - cur11[1])[:2]
    if rotate:
        dual, proj = (-dual[1], dual[0]), (-proj[1], proj[0])
    fdp = (proj[0] * 0x4000 + 0x2000) >> 14
    mv = int((0x4000 * 0x10000) / fdp)
    cur_dist = dotfix14(org[8][0] - org[0][0], org[8][1] - org[0][1], proj[0], proj[1])
    right = mulfix(dotfix14(orus[8][0] - orus[0][0], orus[8][1] - orus[0][1], dual[0], dual[1]), s)
    wrong = mulfix(dotfix14(orus[8][0] - orus[0][0], orus[8][1] - orus[0][1], proj[0], proj[1]), s)
    assert right != wrong, "sdpvtl_mdap: the dual and the projection read the same original distance"
    assert r["points"][8][0] == org[8][0] + mulfix(right - cur_dist, mv), "sdpvtl_mdap: the port disagrees on 8"
    assert r["points"][8][0] != org[8][0] + mulfix(wrong - cur_dist, mv), "sdpvtl_mdap: the wrong reading agrees"
    assert r["points"][13][0] != r["points"][12][0], "sdpvtl_mdap: GC[1] and GC[0] of 9 agree"


def check_sdpvtl_mdap0(r, prog):
    _check_sdpvtl_after_mdap(r, False)


def check_sdpvtl_mdap1(r, prog):
    _check_sdpvtl_after_mdap(r, True)


def check_cutin_twins(r, prog):
    org = _org()
    s = scale_for(12)
    cvt = [mulfix(v, s) for v in CVT]
    for p, c in ((2, 8), (9, 10), (4, 8), (13, 10)):
        assert abs(cvt[c] - org[p][0]) > 68, "cutin_twins: MIAP %d/%d differs by %d" % (p, c, cvt[c] - org[p][0])
    for p, c in ((11, 10), (12, 10), (8, 10), (10, 10)):
        d = org[p][0] - org[0][0]
        assert abs(cvt[c] - d) > 68, "cutin_twins: MIRP %d/%d differs by %d" % (p, c, cvt[c] - d)
    x = [pt[0] for pt in r["points"]]
    assert x[2] == cvt[8] and x[13] == cvt[10], "cutin_twins: MIAP[0] did not land on the cvt"
    assert x[9] == pix_round(org[9][0]) and x[4] == org[4][0], "cutin_twins: MIAP[1] did not keep the outline"
    assert x[11] == org[0][0] + cvt[10] and x[10] == org[0][0] + cvt[10], "cutin_twins: MIRP[00000] not on the cvt"
    assert x[12] == org[0][0] + pix_round(org[12][0] - org[0][0]) and x[8] == org[8][0], "cutin_twins: MIRP[00100]"
    assert r["tags"][4] & 0x08 and r["tags"][8] & 0x08, "cutin_twins: the unmoved twins were not touched"


def check_prep_differs(r, prog):
    """The same program on font 0 (prep RTG) must answer differently: the row measures the prep."""
    base = hint_once(r["code"], prog["ppem"], 0)
    assert base["points"] != r["points"], "%s: font 0 gives the same points; the prep is not observed" % prog["name"]


def check_font_differs(r, prog):
    """The same program on font 0 must answer differently or fail to load there (an opcode or a
    function only the variant defines fails the pedantic load): the row measures the variant."""
    try:
        base = hint_once(r["code"], prog["ppem"], 0)
    except (ftshim.FTError, AssertionError):
        return
    assert (base["points"], base["tags"]) != (r["points"], r["tags"]), \
        "%s: font 0 gives the same outline; the variant is not observed" % prog["name"]


# --- the verification round's rows ------------------------------------------------------------
def _org_at(ppem):
    return scaled_outline(ppem)


def _pv_of(prog):
    """The projection vector a fast-path row sets: the SPVFS operands normalised, or SPVTL[0]'s
    deeper-minus-top edge of the scaled outline (ref2143/ttinterp.c Ins_SxVTL: p1 is the deeper
    operand in zp1, p2 the top in zp2, the vector p1 - p2)."""
    toks = prog["text"].split()
    if "SPVFS" in toks:
        k = toks.index("SPVFS")
        return normalize(int(toks[k - 2]), int(toks[k - 1]))[:2]
    k = toks.index("SPVTL[0]")
    org = _org_at(prog["ppem"])
    a, b = org[int(toks[k - 2])], org[int(toks[k - 1])]
    return normalize(a[0] - b[0], a[1] - b[1])[:2]


def _pv_axis(pv):
    """0 when the fast path is Project_x, 1 for Project_y; the row is degenerate otherwise."""
    assert (pv[0] == 0x4000) != (pv[1] == 0x4000), "pv %s selects no single fast path" % (pv,)
    assert pv[0] != 0 and pv[1] != 0, "pv %s is on the axis: fast and general agree" % (pv,)
    return 0 if pv[0] == 0x4000 else 1


def _pv_ops_model(ppem, pv, axis, proj, pts):
    """The pv_*_ops rows under projection `proj`: MSIRP[0] by 400 from rp0 = 0, MDAP[1], MDRP[00100]
    from 0, MIRP[00000] with cvt 8 from 0 (auto-flip on, no cut-in), MIAP[1] with cvt 10 (cut-in 68),
    each on the point `pts` names for it, moved along `axis` alone (F.P is exactly 0x4000). Also
    answers, per point, the general product's excess on the cur-side vector the instruction reads,
    so a coincidence between the two readings is allowed only where that excess is 0."""
    org, orus, s = _org_at(ppem), _orus(), scale_for(ppem)

    def P(a, b=(0, 0)):
        return proj(a[0] - b[0], a[1] - b[1], pv)

    def excess(a, b=(0, 0)):
        return general(a[0] - b[0], a[1] - b[1], pv) - fast(a[0] - b[0], a[1] - b[1], pv)

    msirp, mdap, mdrp, mirp, miap = pts
    out, ex = {}, {}
    out[msirp] = org[msirp][axis] + 400 - P(org[msirp], org[0])
    ex[msirp] = excess(org[msirp], org[0])
    p = P(org[mdap])
    out[mdap] = org[mdap][axis] + rtg(p) - p
    ex[mdap] = excess(org[mdap])
    od = mulfix(P(orus[mdrp], orus[0]), s)
    out[mdrp] = org[mdrp][axis] + rtg(od) - P(org[mdrp], org[0])
    ex[mdrp] = excess(org[mdrp], org[0])
    cvt = mulfix(CVT[8], s)
    od = mulfix(P(orus[mirp], orus[0]), s)
    if (od ^ cvt) < 0:
        cvt = 0 - cvt
    out[mirp] = org[mirp][axis] + cvt - P(org[mirp], org[0])
    ex[mirp] = excess(org[mirp], org[0])
    cvt = mulfix(CVT[10], s)
    p = P(org[miap])
    d = cvt
    if abs(d - p) > 68:
        d = p
    out[miap] = org[miap][axis] + rtg(d) - p
    ex[miap] = excess(org[miap])
    return out, ex


def _assert_fast(r, prog, right, wrong, excess=None):
    """FreeType's answer is the fast-path model on every listed coordinate and differs from the
    general-product model on each, except where the general product's excess is 0 (a coincidence
    the row's comment allows); at least one coordinate must differ."""
    name = prog["name"]
    differ = 0
    for (p, axis), want in right.items():
        got = r["points"][p][axis]
        assert got == want, "%s: point %d %s is %d, the fast-path model says %d" % (name, p, "xy"[axis], got, want)
        if wrong[(p, axis)] != want:
            differ += 1
        else:
            assert excess is not None and excess[(p, axis)] == 0, \
                "%s: point %d agrees with the general product for no reason" % (name, p)
    assert differ > 0, "%s: no coordinate separates the two readings" % name


def check_pv_ops(r, prog):
    pv = _pv_of(prog)
    axis = _pv_axis(pv)
    pts = (5, 4, 6, 7, 11) if axis == 0 else (4, 5, 6, 7, 11)
    right, ex = _pv_ops_model(prog["ppem"], pv, axis, fast, pts)
    wrong, _ = _pv_ops_model(prog["ppem"], pv, axis, general, pts)

    def keyed(d):
        return dict(((p, axis), v) for p, v in d.items())

    _assert_fast(r, prog, keyed(right), keyed(wrong), keyed(ex))


def check_pv_mdap(r, prog):
    """MDAP[1] on each point the row names: cur + (round(proj) - proj) along the axis."""
    pv = _pv_of(prog)
    axis = _pv_axis(pv)
    org = _org_at(prog["ppem"])
    toks = prog["text"].split()
    pts = [int(toks[k - 1]) for k, t in enumerate(toks) if t == "MDAP[1]"]
    right, wrong = {}, {}
    for p in pts:
        for model, proj in ((right, fast), (wrong, general)):
            d = proj(org[p][0], org[p][1], pv)
            model[(p, axis)] = org[p][axis] + rtg(d) - d
    _assert_fast(r, prog, right, wrong)


def check_pv_readout(r, prog):
    """GC[0] / GC[1] / MD[0] of glyph points under the fast PV, then SCFS onto point 1 under the
    SAME projection (SCFS measures point 1 with it too): both steps modelled under each reading."""
    pv = _pv_of(prog)
    assert _pv_axis(pv) == 0
    org = _org_at(12)
    right, wrong = {}, {}
    for model, proj in ((right, fast), (wrong, general)):
        if "MD[0]" in prog["text"]:
            k = proj(org[4][0] - org[0][0], org[4][1] - org[0][1], pv)
        else:
            k = proj(org[4][0], org[4][1], pv)
        model[(1, 0)] = org[1][0] + k - proj(org[1][0], org[1][1], pv)
    _assert_fast(r, prog, right, wrong)


def check_pv_twilight_readout(r, prog):
    """A twilight point placed at (a, b) is read with GC under the fast vector and copied onto a
    glyph point under an exact axis: the readout is the projection itself."""
    pv = _pv_of(prog)
    axis = _pv_axis(pv)
    toks = prog["text"].split()
    a, b = int(toks[toks.index("SCFS") - 1]), int(toks[toks.index("SCFS", toks.index("SCFS") + 1) - 1])
    into = int(toks[len(toks) - 3])
    right = {(into, axis): fast(a, b, pv)}
    wrong = {(into, axis): general(a, b, pv)}
    _assert_fast(r, prog, right, wrong)


def check_pv_round_flip(r, prog):
    """MDAP[1] on twilight 1 at (31, 3000) under the fast PV, FV x, then GC[0] of it and SCFS onto
    11, both still under that PV: 31 rounds to 0, the general 44 to 64."""
    pv = _pv_of(prog)
    assert _pv_axis(pv) == 0
    org = _org_at(12)
    right, wrong = {}, {}
    for model, proj in ((right, fast), (wrong, general)):
        d = proj(31, 3000, pv)
        cx = 31 + rtg(d) - d
        k = proj(cx, 3000, pv)
        model[(11, 0)] = org[11][0] + k - proj(org[11][0], org[11][1], pv)
    assert right[(11, 0)] == 0 and rtg(general(31, 3000, pv)) == 64, "pv_round_flip: the pixel does not flip"
    _assert_fast(r, prog, right, wrong)


def check_dv_sdpvtl(r, prog):
    """SDPVTL[0] 4 3 on twilight org (236, 1) - (0, 0): the dual normalises to the fast vector; MD[1]
    (original, in twilight: org - org under the dual) and GC[1] of 5 at (100, 3000) are 100."""
    dv = normalize(236, 1)[:2]
    assert _pv_axis(dv) == 0
    right = {(8, 0): fast(100, 3000, dv), (9, 0): fast(100, 3000, dv)}
    wrong = {(8, 0): general(100, 3000, dv), (9, 0): general(100, 3000, dv)}
    _assert_fast(r, prog, right, wrong)


def check_fv_sfvtl(r, prog):
    """SFVTL[0] 2 0 at 18 ppem: FV (0x4000, non-zero) selects the X-only move; the general move
    vector (fv * 0x10000 / F.P, F.P = 0x4000) would have shifted y by mulfix(d, fvy * 4)."""
    org = _org_at(18)
    fv = normalize(org[2][0] - org[0][0], org[2][1] - org[0][1])[:2]
    assert fv[0] == 0x4000 and fv[1] != 0, "fv_sfvtl: FV is %s" % (fv,)
    d = 800 - (org[9][0] - org[0][0])
    assert r["points"][9][0] == org[9][0] + d, "fv_sfvtl: x"
    assert mulfix(d, fv[1] * 4) != 0, "fv_sfvtl: the general move would not have moved y either"
    assert r["points"][9][1] == org[9][1] and r["tags"][9] == r["raw"][1][9] | 0x08, "fv_sfvtl: y moved or touched"


def check_swidth_negative(r, prog):
    """SSW -200 (-150) inside the window: the points inside land at rp0 = 0 plus -150, not +150;
    on the MDRP row 9's original distance (151) is outside the window and it stays put."""
    org, orus, s = _org_at(12), _orus(), scale_for(12)
    swv = mulfix(-200, s)
    assert swv == -150, swv
    inside = (8, 9) if "MIRP" in prog["text"] else (8,)
    for p in inside:
        assert r["points"][p][0] == org[0][0] + swv, "%s: point %d at %d" % (prog["name"], p, r["points"][p][0])
        assert r["points"][p][0] != org[0][0] - swv, "%s: point %d took the flipped sign" % (prog["name"], p)
    if 9 not in inside:
        assert abs(mulfix(orus[9][0] - orus[0][0], s) - swv) >= 250 and r["points"][9] == r["raw"][0][9], "%s: 9" % prog["name"]


def check_mdrp_swidth_below(r, prog):
    org, orus, s = _org_at(12), _orus(), scale_for(12)
    od = mulfix(orus[4][0] - orus[3][0], s)
    swv = mulfix(4, s)
    assert od < 0 and abs(od - swv) < 10, "mdrp_swidth_below: org_dist %d is outside the window" % od
    assert r["points"][4][0] == org[3][0] - swv, "mdrp_swidth_below: point 4 at %d" % r["points"][4][0]
    assert r["points"][4][0] != org[3][0] + swv, "mdrp_swidth_below: the positive branch agrees"


def check_mirp_swidth_below(r, prog):
    org, s = _org_at(12), scale_for(12)
    cvt, swv = mulfix(CVT[4], s), mulfix(100, s)
    assert cvt < 0 and abs(cvt - swv) < 200, "mirp_swidth_below: cvt %d is outside the window" % cvt
    assert r["points"][9][0] == org[4][0] - swv, "mirp_swidth_below: point 9 at %d" % r["points"][9][0]
    assert r["points"][9][0] != org[4][0] + swv, "mirp_swidth_below: the positive branch agrees"


def check_swidth_strict(r, prog):
    org, orus, s = _org_at(12), _orus(), scale_for(12)
    swv, cvt7 = mulfix(200, s), mulfix(CVT[7], s)
    d9, d11 = mulfix(orus[9][0] - orus[0][0], s), mulfix(orus[11][0] - orus[0][0], s)
    assert abs(d9 - swv) == 1 and abs(d11 - swv) == 1 and abs(cvt7 - swv) == 2, (d9, d11, cvt7, swv)
    assert r["points"][9][0] == org[0][0] + cvt7 and r["points"][13][0] == org[0][0] + cvt7, "swidth_strict: MIRP"
    assert r["points"][11][0] == org[0][0] + swv, "swidth_strict: 11 did not snap under SSWCI 2"
    assert r["points"][9][0] != org[0][0] + swv, "swidth_strict: a <= window would have snapped 9"


def check_round_states(r, prog):
    """Every MDRP[00100] here lands somewhere RTG would not have put it."""
    org, orus, s = _org_at(12), _orus(), scale_for(12)
    toks = prog["text"].split()
    ref, groups, cur = 0, [], []
    for k, t in enumerate(toks):
        if t == "SRP0":
            ref = int(toks[k - 1])
        if t in ("SROUND", "S45ROUND", "RDTG", "RUTG", "RTDG") and cur:
            groups.append(cur)
            cur = []
        if t == "MDRP[00100]":
            cur.append((ref, int(toks[k - 1])))
    groups.append(cur)
    for g in groups:
        for ref, p in g:
            d = mulfix(orus[p][0] - orus[ref][0], s)
            assert r["points"][p][0] != org[ref][0] + rtg(d), "%s: %d from %d (%d) rounds like RTG" % (prog["name"], p, ref, d)


def check_zero_orgdist(r, prog):
    org, s = _org_at(12), scale_for(12)
    cvt0 = mulfix(CVT[0], s)
    assert cvt0 < 0
    assert r["points"][9][0] == org[9][0] + 64, "zero_orgdist: 9 was not lifted to the minimum distance"
    assert r["points"][11][0] == org[11][0] - cvt0, "zero_orgdist: 11 did not auto-flip a negative cvt on 0"
    assert r["points"][13][0] == org[13][0] + cvt0, "zero_orgdist: 13 flipped under FLIPOFF"


def check_mdrp_twilight_target(r, prog):
    """org - org (100 - org2.x) rounded, not orus - orus ((0 - 207) * 0.75)."""
    org, orus, s = _org_at(12), _orus(), scale_for(12)
    cd = 100 - org[2][0]
    right = 100 + rtg(cd) - cd
    wrong = 100 + rtg(mulfix(0 - orus[2][0], s)) - cd
    assert right != wrong
    assert r["points"][13][0] == right and r["points"][12][0] == 100, "mdrp_twilight_target: cur %d org %d" % (
        r["points"][13][0], r["points"][12][0])


def check_msirp_twilight_diag_pv(r, prog):
    org = _org_at(12)
    assert r["points"][11][1] != org[2][1] and r["points"][13][0] != org[2][0], "diag_pv: 3's original moved on one axis only"
    assert r["points"][10][1] == org[2][1] and r["points"][12][0] != org[2][0], "diag_pv: X-only moved 4's org.y"
    fv = normalize(236, 1)[:2]
    assert mulfix(r["points"][12][0] - org[2][0], fv[1] * 4) != 0, "diag_pv: the general path would not have moved y"


def check_msirp_twilight_antiparallel(r, prog):
    org = _org_at(12)
    assert r["points"][13][0] == org[2][0] + 100, "antiparallel: org.x is %d" % r["points"][13][0]
    assert r["points"][13][0] != org[2][0] - 100


def check_msirp_twilight_diag(r, prog):
    org = _org_at(12)
    fv = normalize(3, 4)[:2]
    mvy = int((fv[1] * 0x10000) / fv[0])
    assert r["points"][13][0] == org[2][0] + 100 and r["points"][12][1] == org[2][1] + mulfix(100, mvy), \
        "msirp_twilight_diag: (%d, %d)" % (r["points"][13][0], r["points"][12][1])
    assert r["points"][12][1] != org[2][1], "msirp_twilight_diag: y did not move (the X-only reading)"


def check_msirp_twilight_yfast(r, prog):
    org = _org_at(12)
    assert r["points"][13][1] == org[2][1] + 100 and r["points"][13][1] != org[2][1], "msirp_twilight_yfast"


def check_miap_twilight_perp(r, prog):
    cvt = mulfix(CVT[10], scale_for(12))
    got = ((r["points"][12][0], r["points"][10][1]), (r["points"][13][0], r["points"][11][1]))
    assert got == ((0, cvt), (0, cvt)), "miap_twilight_perp: %s" % (got,)
    assert got[0] != (cvt, 0), "miap_twilight_perp: org was written along the projection"


def check_mirp_cutin_gate(r, prog):
    org, s = _org_at(12), scale_for(12)
    cvt = mulfix(CVT[8], s)
    assert abs(cvt - (org[9][0] - 100)) > 68, "cutin_gate: 9 is within the cut-in of cvt 8"
    assert r["points"][9][0] == 100 + rtg(cvt), "cutin_gate: 9 at %d" % r["points"][9][0]
    assert r["points"][9][0] != 100 + rtg(org[9][0] - 100), "cutin_gate: 9 took the cut-in across zones"
    assert r["points"][13][0] == 100 + cvt + rtg(cvt) - cvt, "cutin_gate: twilight 1 at %d" % r["points"][13][0]
    assert r["points"][11][0] == 100 + cvt, "cutin_gate: MIRP[00000] cut in"


def check_sxvtl_zones(r, prog):
    """The deeper operand from zp1 (twilight 0 at (0, 200)), the top from zp2 (glyph 4); swapping the
    zones would read glyph 0 and twilight 4 (at the origin) instead."""
    org = _org_at(12)
    right = normalize(0 - org[4][0], 200 - org[4][1])
    wrong = normalize(org[0][0], org[0][1])
    if "SDPVTL[1]" in prog["text"]:
        right, wrong = (0 - right[1], right[0]), (0 - wrong[1], wrong[0])
        got = (r["points"][11][0], r["points"][10][0])  # GPV leaves y on top: the first SCFS takes it
    else:
        got = (r["points"][13][0], r["points"][12][0])
    assert got == right[:2], "%s: GPV %s, the port says %s" % (prog["name"], got, right[:2])
    assert got != wrong[:2], "%s: the swapped zones agree" % prog["name"]


def check_spvfs_zero(r, prog):
    org = _org_at(12)
    assert (r["points"][13][0], r["points"][12][0]) == (0, 0x4000), "spvfs_zero: PV changed"
    assert r["points"][6][1] == rtg(org[6][1]) and r["points"][6][0] == org[6][0], "spvfs_zero: MDAP did not round y"
    assert r["points"][6][1] != org[6][1], "spvfs_zero: 6's y is already on the grid; pick another point"


def check_spvfs_low16(r, prog):
    right, wrong = normalize(-2, 1)[:2], normalize(65534, 1)[:2]
    got = (r["points"][13][0], r["points"][12][0])
    assert got == right and got != wrong, "spvfs_low16: GPV %s, port %s, unsigned %s" % (got, right, wrong)


def check_sdb_negative(r, prog):
    assert (223 >> 4) - 1 == 12, "sdb_negative: a base of -1 would not match band 12 either"
    assert r["points"][2] == r["raw"][0][2] and r["tags"][2] == r["raw"][1][2], "sdb_negative: 2 moved"


def check_sdb_negative_deltac(r, prog):
    cvt = mulfix(CVT[8], scale_for(12))
    assert r["points"][13][0] == cvt and cvt != cvt + 8 * 8, "sdb_negative_deltac: cvt 8 reads %d" % r["points"][13][0]


def check_sdb_high(r, prog):
    org = _org_at(12)
    assert (63 >> 4) + (65545 & 0xFFFF) == 12 and (63 >> 4) + 65545 != 12
    assert r["points"][2][0] == org[2][0] + 64, "sdb_high: 2 at %d" % r["points"][2][0]





def check_jmpr_past_end(r, prog):
    org = _org_at(12)
    assert r["points"][2][0] == rtg(org[2][0]) != org[2][0], "jmpr_past_end: 2 not rounded (the refusal reading)"
    assert r["points"][13] == r["raw"][0][13], "jmpr_past_end: the SHPIX after the jump ran"


def check_loopcall_negative(r, prog):
    org = _org_at(12)
    assert r["points"][13][0] == org[13][0] + 64 and r["points"][13][0] != org[13][0] + 69, "loopcall_negative"


def check_if_open_at_end(r, prog):
    org = _org_at(12)
    assert r["points"][2][0] == rtg(org[2][0]) != org[2][0], "if_open_at_end: 2 not rounded (the refusal reading)"


def _shifted(r, prog, shifts):
    """Each (point, amount): the point's x moved by exactly that much, and nothing else moved."""
    org = _org_at(prog["ppem"])
    for p, d in shifts:
        assert r["points"][p][0] == org[p][0] + d, "%s: %d at %d, not +%d" % (prog["name"], p, r["points"][p][0], d)
    still = [i for i in range(NPTS) if i not in [p for p, d in shifts]]
    assert all(r["points"][i] == r["raw"][0][i] for i in still), "%s: another point moved" % prog["name"]
    check_font_differs(r, prog)


def check_idef_getvariation(r, prog):
    _shifted(r, prog, [(13, 64)])


def check_fdef_sparse(r, prog):
    _shifted(r, prog, [(13, 64), (12, 32), (11, 16)])


def check_fdef_floor(r, prog):
    _shifted(r, prog, [(13, 32), (12, 64)])


def check_idef_four(r, prog):
    _shifted(r, prog, [(13, 64), (12, 32), (11, 16), (10, 8)])


def check_idef_standard(r, prog):
    assert r["points"][13][0] == 3, "idef_standard: 13 at %d" % r["points"][13][0]
    assert r["points"][1] == r["raw"][0][1], "idef_standard: the IDEF body ran on point 1"
    base = hint_once(r["code"], prog["ppem"], 0)
    assert base["points"] == r["points"], "idef_standard: font 0 answers differently, so the IDEF was reached"


def check_fpgm_getinfo(r, prog):
    org = _org_at(12)
    assert r["points"][13][0] == org[13][0] + 64 and r["points"][13][0] != org[13][0] + 128, "fpgm_getinfo: fn 9"
    assert r["points"][12][0] == 0x1000, "fpgm_getinfo: GETINFO 32 at glyph time is %d" % r["points"][12][0]
    check_font_differs(r, prog)


CHECKS = {
    "mdrp_orus": check_mdrp_orus, "md_orus": check_md_orus, "ip_orus": check_ip_orus, "isect": check_isect,
    "near_perp": check_near_perp, "b1": check_b1, "fdotp_edge": check_fdotp_edge, "normlen": check_normlen,
    "sdpvtl": check_sdpvtl, "sloop_order": check_sloop_order, "near_vertical": check_near_vertical,
    "xonly_fast": check_xonly_fast, "rthg_sround": check_rthg_sround, "alignpts_small": check_alignpts_small,
    "isect_parallel": check_isect_parallel, "sdpvtl_mdap0": check_sdpvtl_mdap0, "sdpvtl_mdap1": check_sdpvtl_mdap1,
    "cutin_twins": check_cutin_twins, "prep_differs": check_prep_differs, "font_differs": check_font_differs,
    "pv_ops": check_pv_ops, "pv_mdap": check_pv_mdap, "pv_readout": check_pv_readout,
    "pv_twilight_readout": check_pv_twilight_readout, "pv_round_flip": check_pv_round_flip,
    "dv_sdpvtl": check_dv_sdpvtl, "fv_sfvtl": check_fv_sfvtl, "swidth_negative": check_swidth_negative,
    "mdrp_swidth_below": check_mdrp_swidth_below, "mirp_swidth_below": check_mirp_swidth_below,
    "swidth_strict": check_swidth_strict, "round_states": check_round_states, "zero_orgdist": check_zero_orgdist,
    "mdrp_twilight_target": check_mdrp_twilight_target, "msirp_twilight_diag_pv": check_msirp_twilight_diag_pv,
    "msirp_twilight_antiparallel": check_msirp_twilight_antiparallel, "msirp_twilight_diag": check_msirp_twilight_diag,
    "msirp_twilight_yfast": check_msirp_twilight_yfast, "miap_twilight_perp": check_miap_twilight_perp,
    "mirp_cutin_gate": check_mirp_cutin_gate, "sxvtl_zones": check_sxvtl_zones, "spvfs_zero": check_spvfs_zero,
    "spvfs_low16": check_spvfs_low16, "sdb_negative": check_sdb_negative,
    "sdb_negative_deltac": check_sdb_negative_deltac, "sdb_high": check_sdb_high,
    "jmpr_past_end": check_jmpr_past_end,
    "loopcall_negative": check_loopcall_negative, "if_open_at_end": check_if_open_at_end,
    "idef_four": check_idef_four, "idef_standard": check_idef_standard, "fpgm_getinfo": check_fpgm_getinfo,
    "idef_getvariation": check_idef_getvariation, "fdef_sparse": check_fdef_sparse, "fdef_floor": check_fdef_floor,
}


def run_check(prog, r):
    if not prog["check"]:
        return
    fn = CHECKS[prog["check"]]
    if fn.__code__.co_argcount == 2:
        fn(r, prog)
    else:
        fn(r)


def run_all():
    out = []
    for prog in PROGRAMS:
        r = run_program(prog)
        run_check(prog, r)
        out.append(r)
    return out


# ----------------------------------------------------------------------------------------------
# The Cyrius module
# ----------------------------------------------------------------------------------------------
CHUNK = 20  # bytes per string literal: 4 characters each keeps the line under 120 bytes

# cyrlint's deferral markers (design A14): the first five exact-case, the rest case-folded. The
# emitted module must contain none of them, in code or in a comment.
DEFERRAL_EXACT = ("NOT_IMPLEMENTED", "SCAFFOLD", "TODO", "FIXME", "XXX")
DEFERRAL_FOLDED = ("deferred", "follow-up", "for now", "not yet", "later bite", "future bite", "out of scope")


def _lit(b):
    return '"' + "".join("\\x%02x" % c for c in b) + '"'


def _wrap(prefix, text, width=110):
    """Comment lines: `prefix` then the words of `text`, wrapped so no line passes `width` bytes;
    continuation lines start with `#  `."""
    lines, cur, sep = [], prefix, "" if prefix.endswith(" ") else " "
    for w in text.split():
        if len((cur + sep + w).encode()) > width and cur != prefix:
            lines.append(cur)
            cur, sep = "#   " + w, " "
        else:
            cur, sep = cur + sep + w, " "
    lines.append(cur)
    return lines


def _chunks_fn(name, data):
    out = ["fn %s(k): i64 {" % name]
    for k in range(0, len(data), CHUNK):
        out.append("    if (k == %d) { return %s; }" % (k // CHUNK, _lit(data[k : k + CHUNK])))
    out += ["    return 0;", "}", ""]
    return out


def _pairs(lines, items, per=2):
    """`per` items to a line, fewer when that would pass 120 bytes (a long program name)."""
    row = []
    for it in items:
        if row and (len(row) == per or len(("    " + "  ".join(row + [it])).encode()) > 120):
            lines.append("    " + "  ".join(row))
            row = []
        row.append(it)
    if row:
        lines.append("    " + "  ".join(row))


def module_lines(results):
    """The module's text as a list of lines, from FreeType's results."""
    fonts = [base_font(f) for f in range(len(FONTS))]
    pp = phantoms()
    ver = ftshim.version_string()
    n = len(PROGRAMS)
    tables = " ".join(sorted(["cmap", "cvt", "fpgm", "glyf", "head", "hhea", "hmtx", "loca", "maxp", "post", "prep"]))
    L = []
    L += [
        "# programs/hint_unit_vectors.cyr — GENERATED by scripts/hint_unit_vectors.py from FreeType %s" % ver,
        "# (classic interpreter, GETINFO version 35, grayscale, FT_LOAD_NO_AUTOHINT). DO NOT EDIT.",
        "#",
        "# A synthetic TrueType font — one simple glyph of two contours, %d points, a 16-entry cvt, a" % NPTS,
        "# two-function fpgm — in %d VARIANTS that differ from font 0 (prep RTG) in their prep, their fpgm" % len(FONTS),
        "# and/or one maxp field (each says which below), and %d glyph PROGRAMS run through FreeType" % n,
        "# itself at their ppem on their font. For each program: the bytes, and what FreeType's glyph",
        "# slot held afterwards — every outline point's hinted position (F26Dot6), its tag byte, and the",
        "# advance. Every program was ALSO loaded under FT_LOAD_PEDANTIC on a fresh face and loaded clean,",
        "# so no instruction was skipped silently. Nothing here was computed by rekha or by a second",
        "# hand-written interpreter.",
        "#",
        "# ⛔ NOT REGENERATED IN CI. CI's Ubuntu ships FreeType 2.13.2, whose move arithmetic (the",
        "# fv * 0x10000 / F_dot_P quotient), ODD/EVEN test, stack margin and DELTAP pop discipline differ",
        "# from the 2.14.3 rekha targets; `fv_b1_regime` below is a move the two versions disagree on.",
        "# Regenerate by hand on a 2.14.x host with",
        "#   python3 scripts/hint_unit_vectors.py emit programs/hint_unit_vectors.cyr",
        "# and review the diff like any other transcription. The emitter lints and formats its output",
        "# before writing it, so this file is gate-clean by construction.",
        "#",
        "# Rules a consumer needs (each measured on FreeType, not read from a spec):",
        "#   * hu_expect_x(p, i) is FreeType's REPORTED x of outline point i: the interpreter's cur.x MINUS",
        "#     cur[pp1].x, because TT_Load_Glyph translates the hinted outline so that pp1 is the origin",
        "#     (ref2143/ttgload.c:2578-2583); hu_expect_y is cur.y as it is. No program here moves pp1,",
        "#     so the subtraction is of 0 — compare cur.x - cur[pp1].x anyway; that is the contract.",
        "#   * hu_expect_tag(p, i) is the tag byte: 1 on-curve, 8 touched in x, 16 touched in y, and on",
        "#     point 0 ALSO 4 (FT_CURVE_TAG_HAS_SCANMODE) with scan_type << 5, which TT_Hint_Glyph sets",
        "#     after any glyph program ran (ref2143/ttgload.c:839-840). Mask with 0x19 (25) for the",
        "#     interpreter's bits: 1 -> ONCURVE, 8 -> TOUCHX, 16 -> TOUCHY.",
        "#   * hu_expect_advance(p) is slot->advance.x: pp2.x - pp1.x after the base layer's grid fit,",
        "#     equal to ((cur[pp2].x - cur[pp1].x) + 32) & -64, which is cur[pp2].x - cur[pp1].x whenever",
        "#     both phantoms sit on the grid, as they do here.",
        "#   * hu_phantom_x/y(k) are pp1..pp4 in FONT UNITS before scaling, per tt_loader_set_pp",
        "#     (ref2143/ttgload.c:1336-1347) for a font with NO `vmtx` and NO `OS/2`: pp1 = (xMin - lsb, 0)",
        "#     = (0, 0) because lsb == xMin, pp2 = (pp1.x + advanceWidth, 0), and TT_Get_VMetrics",
        "#     (ttgload.c:112-138) gives tsb = hhea.ascender - yMax and ah = |ascender - descender|, so",
        "#     pp3 = (0, yMax + tsb) = (0, ascender) and pp4 = (0, pp3.y - ah) = (0, descender). The",
        "#     interpreter then scales all four and rounds pp1.x, pp2.x, pp3.y, pp4.y in cur only",
        "#     (`phantoms` reads back cur 0/448/576/-128 and org 450/600/-150 at 12 ppem).",
        "#   * twilight points are never in the outline; a program that needs one observed reads it out",
        "#     with GC[0] on zone 0 and SCFS on a glyph point (the `read_twilight` idiom in the script).",
        "#     Every twilight index used is below 16, the font's maxTwilightPoints and FreeType's own",
        "#     per-run bound for this glyph.",
        "#   * a program on font 1..%d runs AFTER that font's fpgm and prep ran (the prep at the program's" % (len(FONTS) - 1),
        "#     ppem); the outline, phantoms and cvt are the same in every font, so what its expected values",
        "#     show that font 0 would not is the carry-over of that font's prep, fpgm or maxp field alone.",
        "#",
        "# Accessors (all null-safe: anything out of range answers 0):",
        "#   hu_ft_version()                  cstring, the FreeType that produced this file",
        "#   hu_font_count()                  %d font variants, f in 0..%d (font 0 first, unchanged)" % (len(FONTS), len(FONTS) - 1),
        "#   hu_font_len(f) / hu_font_copy(f, dst)   font f's bytes; copy writes them at dst, answers len",
        "#   hu_outline_points/contours()     %d points (phantoms excluded), %d contours" % (NPTS, len(CONTOUR_ENDS)),
        "#   hu_outline_x/y(i), hu_outline_on(i), hu_contour_end(c)    font units; 0/1; last index",
        "#   hu_phantom_x/y(k)                k 0..3, font units (see above)",
        "#   hu_program_count/name/ppem/font/len(p), hu_program_byte(p, i)    the programs",
        "#   hu_expect_x/y/tag(p, i)          hinted cur (see above) and tag of point i < points",
        "#   hu_expect_advance(p)             hinted advance.x",
        "",
        'fn hu_ft_version(): i64 { return "%s"; }' % ver,
        "",
        "# The fonts: sfnt tables %s." % tables,
        "# maxp of font 0: %d points, %d contours, 2 zones, %d twilight points, %d storage, %d functions,"
        % (NPTS, len(CONTOUR_ENDS), MAX_TWILIGHT, MAX_STORAGE, MAXP_DEFAULT["maxFunctionDefs"]),
        "# %d IDEFs, %d stack elements, %d bytes of instructions. cvt entry i is i * 101 - 505"
        % (MAXP_DEFAULT["maxInstructionDefs"], MAX_STACK, max_program_len()),
        "# (programs/hint_test.cyr's). fpgm of font 0 defines function 3 (adds 5) and 7 (adds 1):",
        "#   " + " ".join(disasm(fpgm_bytes(0))),
        "# Glyph 1 carries no program in these copies. Each font's prep (`prep:`), and, where a font",
        "# differs from font 0 in more than its prep, which tables (`differs:`) and the fpgm listing:",
    ]
    for f, fd in enumerate(FONTS):
        L += _wrap("#   font %d `%s`, %d bytes:" % (f, fd["name"], len(fonts[f])), fd["why"])
        L += _wrap("#     prep: ", " ".join(disasm(prep_bytes(f))))
        if font_differs(f):
            L += _wrap("#     differs: ", ", ".join(font_differs(f)))
        if fd["fpgm"] is not None:
            L += _wrap("#     fpgm: ", " ".join(disasm(fpgm_bytes(f))))
    L += ["fn hu_font_count(): i64 { return %d; }" % len(FONTS), "", "fn hu_font_len(f): i64 {"]
    _pairs(L, ["if (f == %d) { return %d; }" % (f, len(fonts[f])) for f in range(len(FONTS))], 3)
    L += ["    return 0;", "}", ""]
    for f in range(len(FONTS)):
        L += _chunks_fn("hu_f%d_chunk" % f, fonts[f])
    L.append("fn hu_font_chunk(f, k): i64 {")
    _pairs(L, ["if (f == %d) { return hu_f%d_chunk(k); }" % (f, f) for f in range(len(FONTS))], 2)
    L += [
        "    return 0;",
        "}",
        "",
        "fn hu_font_copy(f, dst): i64 {",
        "    if (dst == 0) { return 0; }",
        "    var n = hu_font_len(f);",
        "    var i = 0;",
        "    while (i < n) {",
        "        store8(dst + i, load8(hu_font_chunk(f, i / %d) + (i %% %d)));" % (CHUNK, CHUNK),
        "        i = i + 1;",
        "    }",
        "    return n;",
        "}",
        "",
        "# The outline in font units: upem %d, advance %d, lsb %d (= xMin), bbox %d %d %d %d,"
        % (UPEM, ADVANCE, LSB, XMIN, YMIN, XMAX, YMAX),
        "# hhea ascender %d / descender %d. No coordinate is a multiple of 4, so scale 0.75 (12 ppem) rounds"
        % (ASCENDER, DESCENDER),
        "# every one of them and orus-scaled distances differ from org distances by 1/64 where it matters.",
        "fn hu_outline_points(): i64 { return %d; }" % NPTS,
        "fn hu_outline_contours(): i64 { return %d; }" % len(CONTOUR_ENDS),
        "",
    ]
    for fname, col in (("hu_outline_x", 0), ("hu_outline_y", 1), ("hu_outline_on", 2)):
        L.append("fn %s(i): i64 {" % fname)
        _pairs(L, ["if (i == %d) { return %d; }" % (i, OUTLINE[i][col]) for i in range(NPTS)], 3)
        L += ["    return 0;", "}", ""]
    L.append("fn hu_contour_end(c): i64 {")
    _pairs(L, ["if (c == %d) { return %d; }" % (c, e) for c, e in enumerate(CONTOUR_ENDS)], 2)
    L += ["    return 0;", "}", ""]
    for fname, col in (("hu_phantom_x", 0), ("hu_phantom_y", 1)):
        L.append("fn %s(k): i64 {" % fname)
        _pairs(L, ["if (k == %d) { return %d; }" % (k, pp[k][col]) for k in range(4)], 2)
        L += ["    return 0;", "}", ""]
    L += [
        "# The programs. Each hu_c<p>(k) holds the bytes in %d-byte literals; hu_e<p>(i, f) the expected" % CHUNK,
        "# x (f 0), y (f 1) and tag (f 2) of outline point i. The comment above each is the program's",
        "# purpose and its listing; `font N` names the variant it ran on.",
        "fn hu_pick(f, x, y, t): i64 {",
        "    if (f == 0) { return x; }",
        "    if (f == 1) { return y; }",
        "    return t;",
        "}",
        "",
        "fn hu_program_count(): i64 { return %d; }" % n,
        "",
    ]
    for p, (prog, r) in enumerate(zip(PROGRAMS, results)):
        head = "# %d %s — font %d, %d ppem, %d bytes:" % (p, prog["name"], prog["font"], prog["ppem"], len(r["code"]))
        L += _wrap(head, prog["proves"])
        L += _wrap("#   ", " ".join(disasm(r["code"])))
        L += _chunks_fn("hu_c%d" % p, r["code"])
        L.append("fn hu_e%d(i, f): i64 {" % p)
        _pairs(
            L,
            ["if (i == %d) { return hu_pick(f, %d, %d, %d); }" % (i, r["points"][i][0], r["points"][i][1], r["tags"][i])
             for i in range(NPTS)],
            2,
        )
        L += ["    return 0;", "}", ""]
    L.append("fn hu_program_name(p): i64 {")
    _pairs(L, ['if (p == %d) { return "%s"; }' % (p, prog["name"]) for p, prog in enumerate(PROGRAMS)], 2)
    L += ["    return 0;", "}", ""]
    L.append("fn hu_program_ppem(p): i64 {")
    _pairs(L, ["if (p == %d) { return %d; }" % (p, prog["ppem"]) for p, prog in enumerate(PROGRAMS)], 3)
    L += ["    return 0;", "}", ""]
    L.append("fn hu_program_font(p): i64 {")
    _pairs(L, ["if (p == %d) { return %d; }" % (p, prog["font"]) for p, prog in enumerate(PROGRAMS)], 3)
    L += ["    return 0;", "}", ""]
    L.append("fn hu_program_len(p): i64 {")
    _pairs(L, ["if (p == %d) { return %d; }" % (p, len(r["code"])) for p, r in enumerate(results)], 3)
    L += ["    return 0;", "}", ""]
    L.append("fn hu_code_chunk(p, k): i64 {")
    _pairs(L, ["if (p == %d) { return hu_c%d(k); }" % (p, p) for p in range(n)], 3)
    L += ["    return 0;", "}", ""]
    L += [
        "fn hu_program_byte(p, i): i64 {",
        "    if (i < 0) { return 0; }",
        "    if (i >= hu_program_len(p)) { return 0; }",
        "    return load8(hu_code_chunk(p, i / %d) + (i %% %d));" % (CHUNK, CHUNK),
        "}",
        "",
        "fn hu_expect(p, i, f): i64 {",
        "    if (i < 0) { return 0; }",
        "    if (i >= %d) { return 0; }" % NPTS,
    ]
    _pairs(L, ["if (p == %d) { return hu_e%d(i, f); }" % (p, p) for p in range(n)], 3)
    L += [
        "    return 0;",
        "}",
        "",
        "fn hu_expect_x(p, i): i64 { return hu_expect(p, i, 0); }",
        "fn hu_expect_y(p, i): i64 { return hu_expect(p, i, 1); }",
        "fn hu_expect_tag(p, i): i64 { return hu_expect(p, i, 2); }",
        "",
        "fn hu_expect_advance(p): i64 {",
    ]
    _pairs(L, ["if (p == %d) { return %d; }" % (p, r["advance"]) for p, r in enumerate(results)], 3)
    L += ["    return 0;", "}", ""]
    return L


def _lint_ok(path):
    """`cyrius lint <path> --strict` must exit 0 and print no warn/deferral line (the CI gate)."""
    r = subprocess.run(["cyrius", "lint", path, "--strict"], capture_output=True, text=True)
    out = r.stdout + r.stderr
    bad = [ln for ln in out.split("\n") if ln.lstrip().startswith(("warn ", "deferral "))]
    if r.returncode != 0 or bad:
        return "cyrius lint --strict: rc %d\n%s" % (r.returncode, out)
    return None


def _fmt_ok(path, tmpdir):
    """`cyrius fmt` on a COPY must change nothing (never --check: it is a false negative)."""
    copy = os.path.join(tmpdir, "fmt_copy.cyr")
    shutil.copyfile(path, copy)
    r = subprocess.run(["cyrius", "fmt", copy], capture_output=True, text=True)
    if r.returncode != 0:
        return "cyrius fmt: rc %d\n%s%s" % (r.returncode, r.stdout, r.stderr)
    a, b = open(path, "rb").read(), open(copy, "rb").read()
    if a != b:
        r2 = subprocess.run(["diff", path, copy], capture_output=True, text=True)
        return "cyrius fmt rewrote the output:\n%s" % r2.stdout
    return None


def self_check(lines):
    """The static gates: 120 BYTES per line, no trailing whitespace, no deferral word."""
    for k, line in enumerate(lines, 1):
        assert len(line.encode()) <= 120, "line %d is %d bytes" % (k, len(line.encode()))
        assert not line.endswith(" "), "line %d has trailing whitespace" % k
        for w in DEFERRAL_EXACT:
            assert w not in line, "line %d holds the deferral word %r" % (k, w)
        low = line.lower()
        for w in DEFERRAL_FOLDED:
            assert w not in low, "line %d holds the deferral word %r" % (k, w)


def emit(path):
    results = run_all()
    L = module_lines(results)
    self_check(L)
    src = "\n".join(L)
    tmpdir = tempfile.mkdtemp(prefix="hint_unit_vectors.")
    try:
        cand = os.path.join(tmpdir, os.path.basename(path))
        open(cand, "w").write(src)
        why = _lint_ok(cand) or _fmt_ok(cand, tmpdir)
        if why:
            sys.exit("refusing to write %s:\n%s" % (path, why))
        shutil.move(cand, path)
    finally:
        shutil.rmtree(tmpdir, ignore_errors=True)
    print("wrote %s: FreeType %s, %d fonts, %d programs, %d lines, lint --strict and fmt clean"
          % (path, ftshim.version_string(), len(FONTS), len(PROGRAMS), len(L)))


def cmd_list(argv):
    results = run_all()
    print("# FreeType %s (%s), interpreter-version %d, %d fonts, %d programs, all clean under FT_LOAD_PEDANTIC"
          % (ftshim.version_string(), ftshim.library_path(), ftshim.INTERPRETER_VERSION, len(FONTS), len(PROGRAMS)))
    for f, fd in enumerate(FONTS):
        extra = ("  [%s]" % ", ".join(font_differs(f))) if font_differs(f) else ""
        print("# font %d %-13s prep: %s%s" % (f, fd["name"], fd["prep"], extra))
    for p, (prog, r) in enumerate(zip(PROGRAMS, results)):
        moved = sum(1 for i in range(NPTS) if r["points"][i] != r["raw"][0][i] or r["tags"][i] != r["raw"][1][i])
        print("%2d %-22s f%d %3d ppem %3d B  %2d pts changed  adv %4d  %s"
              % (p, prog["name"], prog["font"], prog["ppem"], len(r["code"]), moved, r["advance"], prog["proves"]))


def cmd_dump(argv):
    if not argv:
        sys.exit("dump needs a program name; `list` shows them")
    names = [p["name"] for p in PROGRAMS]
    if argv[0] not in names:
        sys.exit("no program %r; `list` shows them" % argv[0])
    prog = PROGRAMS[names.index(argv[0])]
    r = run_program(prog)
    run_check(prog, r)
    print("%s — font %d, %d ppem, %d bytes, advance %d: %s"
          % (prog["name"], prog["font"], prog["ppem"], len(r["code"]), r["advance"], prog["proves"]))
    print("  " + "\n  ".join(disasm(r["code"])))
    print("  bytes: " + " ".join("%02X" % b for b in r["code"]))
    print("%4s %-16s %-16s %5s   %s" % ("i", "before", "after", "tag", "delta"))
    for i in range(NPTS):
        a, b, t = r["raw"][0][i], r["points"][i], r["tags"][i]
        d = (b[0] - a[0], b[1] - a[1])
        print("%4d %-16s %-16s %5d %s %s" % (i, a, b, t, " *" if d != (0, 0) or t != r["raw"][1][i] else "  ", d if d != (0, 0) else ""))


def main():
    cmds = {"emit": None, "list": cmd_list, "dump": cmd_dump}
    if len(sys.argv) < 2 or sys.argv[1] not in cmds:
        print(__doc__)
        return 2
    if sys.argv[1] == "emit":
        emit(sys.argv[2] if len(sys.argv) > 2 else "programs/hint_unit_vectors.cyr")
        return 0
    return cmds[sys.argv[1]](sys.argv[2:]) or 0


if __name__ == "__main__":
    sys.exit(main())
